// Creates the e2e accounts and payer fixtures in a LOCAL PocketBase, as a superuser, the way an
// admin would. Payer tokens are generated by the backend, so they are handed to the specs in
// playwright/.auth/fixtures.json. Never runs against a deployed backend.
//
// Backend: PB_TEST_URL / PB_INTERNAL_URL (set by `npm run test:e2e:pb`), else http://localhost:8090
// (docker compose). Superuser: PB_TEST_SUPERUSER_* (test:e2e:pb), else ./.env.seed (scripts/dev-seed.sh).
import { randomBytes } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { ACCOUNTS_FILE, accountEmail, FIXTURES_FILE, PROJECTS, type Accounts, type Fixtures } from "./accounts";

const PB = (process.env.PB_TEST_URL || process.env.PB_INTERNAL_URL || "http://localhost:8090").replace(/\/+$/, "");

function seedFile(): Record<string, string> {
  if (!existsSync(".env.seed")) return {};
  return Object.fromEntries(readFileSync(".env.seed", "utf8").split("\n").filter((l) => /^[A-Z_]+=/.test(l)).map((l) => [l.slice(0, l.indexOf("=")), l.slice(l.indexOf("=") + 1)]));
}

async function api(method: string, path: string, token: string, body?: unknown) {
  const res = await fetch(PB + path, {
    method,
    headers: { Authorization: token, "Content-Type": "application/json", "CF-Connecting-IP": "10.255.255.254" },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(`${method} ${path} -> ${res.status} ${JSON.stringify(json)}`);
  return json;
}

export default async function globalSetup() {
  if (!/^http:\/\/(127\.0\.0\.1|localhost)(:\d+)?$/.test(PB)) throw new Error(`e2e fixtures only go into a local PocketBase, not ${PB}`);
  // Fresh client IPs every run: the app's rate limits live in its memory and outlast a run.
  process.env.E2E_RUN_SALT = randomBytes(4).toString("hex");

  const seed = seedFile();
  const identity = process.env.PB_TEST_SUPERUSER_EMAIL || seed.DEV_SUPERUSER_EMAIL;
  const suPassword = process.env.PB_TEST_SUPERUSER_PASSWORD || seed.DEV_SUPERUSER_PASSWORD;
  if (!identity || !suPassword) throw new Error("No superuser login: run `npm run test:e2e:pb`, or scripts/dev-seed.sh first");
  const login = await fetch(`${PB}/api/collections/_superusers/auth-with-password`, {
    method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ identity, password: suPassword }),
  });
  if (!login.ok) throw new Error(`superuser login failed: ${login.status}`);
  const su = ((await login.json()) as { token: string }).token;

  const password = randomBytes(12).toString("base64url");
  async function upsertUser(email: string): Promise<string> {
    const found = await api("GET", `/api/collections/users/records?filter=${encodeURIComponent(`email='${email}'`)}`, su);
    const body = { email, password, passwordConfirm: password, verified: true };
    if (found.items[0]) return (await api("PATCH", `/api/collections/users/records/${found.items[0].id}`, su, body)).id;
    return (await api("POST", "/api/collections/users/records", su, body)).id;
  }
  async function setProfile(owner: string, profile: { display_name: string; paynow_id: string } | null) {
    const found = await api("GET", `/api/collections/profiles/records?filter=${encodeURIComponent(`owner='${owner}'`)}`, su);
    if (found.items[0]) await api("DELETE", `/api/collections/profiles/records/${found.items[0].id}`, su);
    if (profile) await api("POST", "/api/collections/profiles/records", su, { owner, paynow_type: "mobile", ...profile });
  }

  const organiserId = await upsertUser(accountEmail("organiser"));
  await setProfile(organiserId, { display_name: "E2E Organiser", paynow_id: "91234567" });
  for (const project of PROJECTS) {
    await setProfile(await upsertUser(accountEmail("fresh", project)), null); // AC-F02-01 needs an organiser with no profile
    await setProfile(await upsertUser(accountEmail("paynow", project)), { display_name: "PayNow Changer", paynow_id: "91234567" });
    await upsertUser(accountEmail("other", project));
    await upsertUser(accountEmail("signin", project));
  }

  // F04 fixtures: Dinner (open) with Priya (valid) and Ravi (revoked); Old (expired yesterday) with Tan.
  const dinner = await api("POST", "/api/collections/collections/records", su, { owner: organiserId, title: "Dinner" });
  const priya = await api("POST", "/api/collections/payers/records", su, { collection: dinner.id, first_name: "Priya", amount_cents: 2500, reference: "DINN-PRIYA" });
  const ravi = await api("POST", "/api/collections/payers/records", su, { collection: dinner.id, first_name: "Ravi", amount_cents: 2501, reference: "DINN-RAVI" });
  await api("PATCH", `/api/collections/payers/records/${ravi.id}`, su, { revoked: true });
  const old = await api("POST", "/api/collections/collections/records", su, { owner: organiserId, title: "Old", expires_at: new Date(Date.now() - 86_400_000).toISOString() });
  const tan = await api("POST", "/api/collections/payers/records", su, { collection: old.id, first_name: "Tan", amount_cents: 1000, reference: "OLD-TAN" });

  mkdirSync("playwright/.auth", { recursive: true });
  writeFileSync(ACCOUNTS_FILE, JSON.stringify({ password } satisfies Accounts), { mode: 0o600 });
  writeFileSync(FIXTURES_FILE, JSON.stringify({ dinnerId: dinner.id, valid: priya.token, revoked: ravi.token, expired: tan.token } satisfies Fixtures));
}
